function AtelierPro({token,user,onLogout}:{token:string;user:PlatformUser;onLogout:()=>void}){
  const [tab,setTab]=useState<'dashboard'|'schools'|'access'|'team'|'notifications'|'audit'|'diagnostics'>('dashboard');
  // Server-computed identity and menu: a PLATFORM_CUSTOM account only sees (and only loads) what its roles open.
  const [me,setMe]=useState<PlatformMe|null>(null);
  const can=(key:string)=>!!me?.menu.some(m=>m.key===key);
  const has=(cap:string)=>!!me?.permissions.includes(cap);
  useEffect(()=>{replaceMobileRoot('platform','dashboard');const h=(e:Event)=>{const d=(e as CustomEvent).detail;if(d?.edusyncScope==='platform'&&d.edusyncScreen)setTab(d.edusyncScreen)};window.addEventListener('edusync:android-back',h);return()=>window.removeEventListener('edusync:android-back',h)},[]);
  const goTab=(next:typeof tab)=>{if(next!==tab)pushMobileScreen('platform',next);setTab(next)};
  const [dashboard,setDashboard]=useState<any>(null),[schools,setSchools]=useState<any>({items:[]}),[access,setAccess]=useState<any>({items:[]}),[audit,setAudit]=useState<any>({items:[]}),[diag,setDiag]=useState<any>(null),[systemNotifications,setSystemNotifications]=useState<any>({items:[]});
  const [q,setQ]=useState(''),[status,setStatus]=useState(''),[accessQ,setAccessQ]=useState(''),[error,setError]=useState('');
  const [notificationOpen,setNotificationOpen]=useState(false);
  const [schoolAction,setSchoolAction]=useState<{kind:'suspend'|'reactivate'|'admin';school:any}|null>(null);
  const [schoolDetailId,setSchoolDetailId]=useState<string|null>(null);
  const [creatingSchool,setCreatingSchool]=useState(false);
  const [collaboratorAction,setCollaboratorAction]=useState<any|null>(null);
  // Step-up (decision 2026-10-13): sensitive actions ask for a fresh code through this dialog, then resume by themselves.
  const [stepUp,setStepUp]=useState<((ok:boolean)=>void)|null>(null);
  useEffect(()=>{setStepUpHandler(()=>new Promise<boolean>(resolve=>setStepUp(()=>resolve)));return()=>setStepUpHandler(null)},[]);
  const schoolSchema=z.object({name:z.string().trim().min(2,'Le nom de l’école est obligatoire.'),code:z.string().trim().min(2,'Le code établissement est obligatoire.').max(24,'Le code est trop long.')});type SchoolCreateForm=z.infer<typeof schoolSchema>;const schoolForm=useForm<SchoolCreateForm>({resolver:zodResolver(schoolSchema),defaultValues:{name:'',code:''},...formDefaults});
  async function refresh(current:PlatformMe|null=me){if(!current)return;setError('');const allowed=new Set(current.menu.map(m=>m.key));
    const jobs:[string,()=>Promise<void>][]=[['dashboard',async()=>setDashboard(await platformDashboard(token))],['schools',async()=>setSchools(await platformSchoolsPage(token,q,status,0))],['access',async()=>setAccess(await platformAccess(token,accessQ,0))],];
    const settled=await Promise.allSettled(jobs.filter(([k])=>allowed.has(k)).map(([,run])=>run()));const failed=settled.find(r=>r.status==='rejected') as PromiseRejectedResult|undefined;if(failed)setError(friendlyError(failed.reason))}
  useEffect(()=>{let alive=true;platformMe(token).then(m=>{if(!alive)return;setMe(m);if(!m.menu.some(x=>x.key==='dashboard')&&m.menu[0])setTab(m.menu[0].key as typeof tab);void refresh(m)}).catch(e=>alive&&setError(friendlyError(e)));return()=>{alive=false}},[token]);
  async function searchSchools(){try{setSchools(await platformSchoolsPage(token,q,status,0))}catch(e){setError(friendlyError(e))}}
  async function searchAccess(){try{setAccess(await platformAccess(token,accessQ,0))}catch(e){setError(friendlyError(e))}}
  const submit=schoolForm.handleSubmit(async values=>{try{await createSchool(token,{name:values.name.trim(),code:values.code.trim().toUpperCase()});schoolForm.reset();toast.success('École créée');await refresh()}catch(e){setError(friendlyError(e))}});
  const NAV_DEF:[typeof tab,string,string][]=[['dashboard','cockpit','Tableau de bord'],['schools','school','Écoles'],['access','lock','Accès écoles'],['team','users','Équipe plateforme'],['notifications','bell','Notifications système'],['audit','audit','Journal d’audit'],['diagnostics','pulse','État du service']];
  const nav:any[]=NAV_DEF.filter(([k])=>can(k)).map(([k,icon,label])=>[icon,label,tab===k,()=>goTab(k),k]);
  return <Shell title="Atelier Pro" subtitle="Pilotage et administration de la plateforme EduSync" onLogout={onLogout} nav={nav} user={user} token={token} roleLabel={me?.roles.map(r=>r.label).join(' · ')}>
    {error&&<div className="error">{error}</div>}
    {me&&typeof me.active_managers==='number'&&me.active_managers<(me.recommended_managers||2)&&<div className="es-alert es-alert-warn" role="status"><NavGlyph g="alert" size={16}/><span><b>Un seul Manager système actif.</b> Ajoutez un second Manager depuis « Équipe plateforme » : en cas de téléphone perdu, il pourra rétablir votre accès sans intervention technique.</span></div>}
    {stepUp&&<StepUpDialog token={token} onDone={ok=>{stepUp(ok);setStepUp(null)}}/>}
    {!me&&!error&&<div className="es-skeleton" aria-busy="true"><i/><i/><i/></div>}
    {creatingSchool&&<Suspense fallback={null}><SchoolCreateDialog token={token} onClose={()=>setCreatingSchool(false)} onCreated={async x=>{setCreatingSchool(false);await searchSchools();if(has('platform.school_admin.bootstrap'))setSchoolAction({kind:'admin',school:x})}}/></Suspense>}
    {tab==='team'&&can('team')&&<Suspense fallback={<div className="es-skeleton" aria-busy="true"><i/><i/><i/></div>}><TeamPage token={token}/></Suspense>}
    {tab==='dashboard'&&<><div className="kpis"><Kpi icon="school" value={dashboard?.schools?.total??'—'} label="Écoles"/><Kpi icon="checkCircle" value={dashboard?.schools?.active??'—'} label="Actives"/><Kpi icon="users" value={dashboard?.active_memberships??'—'} label="Accès actifs"/><Kpi icon="sync" value={dashboard?.outbox_pending??'—'} label="Événements à diffuser"/></div><Panel title="Activité récente" subtitle="Derniers événements auditables de la plateforme et des écoles."><div className="dataTable"><div className="row platformAuditRow header"><span>Date</span><span>École</span><span>Action</span><span>Résultat</span></div>{(dashboard?.recent_activity??[]).map((x:any)=><div className="row platformAuditRow" key={x.id}><span>{new Date(x.occurred_at).toLocaleString()}</span><span>{x.school_code||'Plateforme'}</span><span><b title={x.action}>{auditActionLabel(x.action)}</b><small>{x.actor||'Système'}</small></span><span><em className={x.result==='SUCCESS'?'pill ready':'pill'}>{resultLabel(x.result)}</em></span></div>)}</div></Panel></>}
    {tab==='schools'&&<Panel title="Annuaire des écoles" subtitle="Création, statut, administrateur initial et actions de gouvernance, toutes tracées."><form className="inlineForm" onSubmit={e=>{e.preventDefault();void searchSchools()}}><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Rechercher nom ou code"/><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Tous les statuts</option><option value="ACTIVE">Active</option><option value="SUSPENDED">Suspendue</option><option value="DISABLED">Désactivée</option></select><button>Rechercher</button></form>{has('platform.schools.create')&&<div className="moduleToolbar"><button className="sc-new" onClick={()=>setCreatingSchool(true)}>+ Nouvelle école</button></div>}<div className="dataTable"><div className="row platformSchoolActionRow header"><span>École</span><span>Statut</span><span>Accès</span><span>Admin initial</span><span>Actions</span></div>{schools.items.map((x:any)=><div className="row platformSchoolActionRow" key={x.id}><span><b>{x.name}</b><small>{x.code}</small></span><span><em className={x.status==='ACTIVE'?'pill ready':'pill'}>{schoolStatusLabel(x.status)}</em></span><span>{x.active_memberships}</span><span>{x.admin_count>0?'Configuré':'À créer'}</span><span className="rowActions"><button className="ghost" onClick={()=>setSchoolDetailId(x.id)}>Fiche</button>{x.admin_count===0&&has('platform.school_admin.bootstrap')&&<button className="ghost" onClick={()=>setSchoolAction({kind:'admin',school:x})}>Créer admin</button>}{x.status==='ACTIVE'&&has('platform.schools.suspend')?<button className="danger" onClick={()=>setSchoolAction({kind:'suspend',school:x})}>Suspendre</button>:x.status==='SUSPENDED'&&has('platform.schools.activate')?<button onClick={()=>setSchoolAction({kind:'reactivate',school:x})}>Réactiver</button>:null}</span></div>)}</div>{schools.has_more&&<button className="ghost" onClick={async()=>{const n=await platformSchoolsPage(token,q,status,schools.offset+schools.limit);setSchools({...n,items:[...schools.items,...n.items]})}}>Charger plus</button>}</Panel>}
    {tab==='access'&&<Panel title="Accès et identités" subtitle="Comptes et rattachements aux écoles. Les droits métier sont gérés par rôle dans chaque école."><form className="inlineForm" onSubmit={e=>{e.preventDefault();void searchAccess()}}><input value={accessQ} onChange={e=>setAccessQ(e.target.value)} placeholder="Nom ou adresse e-mail"/><button>Rechercher</button></form><div className="dataTable"><div className="row platformAccessRow header"><span>Utilisateur</span><span>Type</span><span>Écoles</span><span>Statut</span></div>{access.items.map((x:any)=><div className="row platformAccessRow" key={x.id}><span><b>{x.full_name}</b><small>{x.email}</small></span><span>{x.collaborator_platform?'Collaborateur plateforme':x.is_platform_admin?'Manager système':'Compte école'}</span><span>{x.schools||'—'}</span><span><em className={x.active?'pill ready':'pill'}>{x.active?'Actif':'Désactivé'}</em>{access.can_manage_collaborators&&x.active&&<button className="ghost compactAction" onClick={()=>setCollaboratorAction(x)}>{x.collaborator_platform?'Retirer collaboration':'Donner accès plateforme'}</button>}</span></div>)}</div>{access.has_more&&<button className="ghost" onClick={async()=>{const n=await platformAccess(token,accessQ,access.offset+access.limit);setAccess({...n,items:[...access.items,...n.items]})}}>Charger plus</button>}</Panel>}
    {tab==='notifications'&&<Panel title="Notifications" subtitle="Messages internes ciblés vers les écoles ou l’équipe plateforme. Chaque envoi est audité ; aucun SMS n’est envoyé."><Suspense fallback={<div className="es-skeleton" aria-busy="true"><i/><i/><i/></div>}><CampaignsPanel token={token} canTeam={has('platform.collaborators.manage')}/></Suspense></Panel>}
    {tab==='audit'&&<Panel title="Journal d’audit" subtitle="Toutes les actions tracées de la plateforme et des écoles. Rien ne peut y être modifié ni supprimé."><Suspense fallback={<div className="es-skeleton" aria-busy="true"><i/><i/><i/></div>}><AuditPanel token={token} canExport={has('platform.audit.export')}/></Suspense></Panel>}
    {tab==='diagnostics'&&<Panel title="Santé du système" subtitle="Mesures réelles prises à l’instant : temps de réponse, signaux des tâches de fond, erreurs, sauvegardes."><Suspense fallback={<div className="es-skeleton" aria-busy="true"><i/><i/><i/></div>}><HealthPanel token={token}/></Suspense></Panel>}
    {notificationOpen&&<PlatformNotificationDialog token={token} schools={schools.items} onClose={()=>setNotificationOpen(false)} onDone={async()=>{setNotificationOpen(false);setSystemNotifications(await platformSystemNotifications(token,0));await refresh()}}/>}
    {schoolDetailId&&<PlatformSchoolDetailDialog canManage={has('platform.access.manage')} token={token} schoolId={schoolDetailId} onClose={()=>setSchoolDetailId(null)} onChanged={refresh}/>}
    {schoolAction&&<PlatformSchoolActionDialog token={token} action={schoolAction} onClose={()=>setSchoolAction(null)} onDone={async()=>{setSchoolAction(null);await refresh()}}/>}
  {collaboratorAction&&<PlatformCollaboratorDialog user={collaboratorAction} onClose={()=>setCollaboratorAction(null)} onConfirm={async(reason)=>{try{if(collaboratorAction.collaborator_platform)await platformRevokeCollaborator(token,collaboratorAction.id,reason);else await platformGrantCollaborator(token,collaboratorAction.id,reason);toast.success(collaboratorAction.collaborator_platform?'Collaboration retirée':'Collaborateur plateforme activé');setCollaboratorAction(null);await searchAccess()}catch(e){setError(friendlyError(e))}}}/>}
  </Shell>
}

function PlatformSchoolDetailDialog({token,schoolId,onClose,onChanged,canManage}:{token:string;schoolId:string;onClose:()=>void;onChanged:()=>Promise<void>;canManage:boolean}){
 const [data,setData]=useState<any>(null),[roles,setRoles]=useState<any[]>([]),[error,setError]=useState(''),[busy,setBusy]=useState('');
 async function load(){try{setError('');const [d,r]=await Promise.all([platformSchoolDetail(token,schoolId),platformRbacRoles(token)]);setData(d);setRoles(r)}catch(e){setError(friendlyError(e))}}
 useEffect(()=>{void load()},[schoolId]);
 async function toggle(m:any){const reason='Gouvernance accès Atelier Pro';try{setBusy(m.membership_id);await platformMembershipState(token,m.membership_id,!m.membership_active,reason);toast.success(m.membership_active?'Accès désactivé':'Accès réactivé');await load();await onChanged()}catch(e){setError(friendlyError(e))}finally{setBusy('')}}
 async function role(m:any,code:string){if(!code)return;try{setBusy(m.membership_id);await platformAssignRole(token,m.membership_id,code,'Attribution de rôle par le Manager système');toast.success('Rôle attribué');await load();await onChanged()}catch(e){setError(friendlyError(e))}finally{setBusy('')}}
 async function revoke(m:any,code:string){try{setBusy(m.membership_id);await platformRevokeRole(token,m.membership_id,code,'Retrait de rôle par le Manager système');toast.success('Rôle retiré');await load();await onChanged()}catch(e){setError(friendlyError(e))}finally{setBusy('')}}
 if(!data)return <div className="modalBackdrop"><div className="platformActionModal"><div className="modalHead"><h3>Fiche école</h3><button onClick={onClose}>×</button></div>{error||'Chargement…'}</div></div>;
 const gates=Object.entries(data.readiness) as [string,boolean][];const labels:any={school_identity:'Identité école',initial_admin:'Administrateur initial',academic_year:'Année scolaire',classes:'Classes',fee_catalog:'Catalogue des frais'};
 return <div className="modalBackdrop"><div className="platformActionModal platformSchoolDetail" role="dialog" aria-modal="true"><div className="modalHead"><div><h3>{data.school.name}</h3><p>{data.school.code} · {schoolStatusLabel(data.school.status)}</p></div><button onClick={onClose}>×</button></div>{error&&<div className="error">{error}</div>}<div className="summaryStrip"><span><b>{data.ready_count}/{data.total_gates}</b> étapes de mise en service</span><span><b>{data.memberships}</b> accès actifs</span></div><div className="diagnosticGrid">{gates.map(([k,v])=><p key={k}>{labels[k]||k} <em className={v?'pill ready':'pill'}>{v?'PRÊT':'À CONFIGURER'}</em></p>)}</div><h4>Accès de l’école</h4><div className="dataTable"><div className="row platformAccessRow header"><span>Utilisateur</span><span>Rôles</span><span>Rôle à attribuer</span><span>Accès</span></div>{data.users.map((m:any)=><div className="row platformAccessRow" key={m.membership_id}><span><b>{m.full_name}</b><small>{m.email}</small></span><span>{m.role_assignments?.length?<div className="roleChips">{m.role_assignments.map((r:any)=><button key={r.assignment_id} className="ghost" disabled={!canManage||busy===m.membership_id} title="Retirer ce rôle" onClick={()=>void revoke(m,r.role_code)}>{r.role_label||r.role_code} ×</button>)}</div>:'Aucun rôle'}</span><span><select disabled={!canManage||!m.membership_active||busy===m.membership_id} defaultValue="" onChange={e=>void role(m,e.target.value)}><option value="">Attribuer…</option>{roles.map(r=><option key={r.id} value={r.code}>{r.label}</option>)}</select></span><span><button className={m.membership_active?'danger':''} disabled={!canManage||busy===m.membership_id} onClick={()=>void toggle(m)}>{m.membership_active?'Désactiver':'Réactiver'}</button></span></div>)}</div><div className="modalFooter"><button onClick={onClose}>Fermer</button></div></div></div>
}

function PlatformNotificationDialog({token,schools,onClose,onDone}:{token:string;schools:any[];onClose:()=>void;onDone:()=>Promise<void>}){
 const schema=z.object({title:z.string().trim().min(2,'Titre obligatoire').max(180),body:z.string().trim().min(2,'Message obligatoire').max(2000),severity:z.enum(['INFO','WARNING','CRITICAL']),target_scope:z.enum(['ALL_ACTIVE_SCHOOLS','SCHOOL']),target_school_id:z.string().optional()}).superRefine((v,c)=>{if(v.target_scope==='SCHOOL'&&!v.target_school_id)c.addIssue({code:'custom',path:['target_school_id'],message:'Choisissez une école active.'})});type F=z.infer<typeof schema>;const f=useForm<F>({resolver:zodResolver(schema),defaultValues:{title:'',body:'',severity:'INFO',target_scope:'ALL_ACTIVE_SCHOOLS',target_school_id:''},...formDefaults});const [error,setError]=useState('');const scope=f.watch('target_scope');const submit=f.handleSubmit(async v=>{try{setError('');const r=await sendPlatformSystemNotification(token,{title:v.title.trim(),body:v.body.trim(),severity:v.severity,target_scope:v.target_scope,target_school_id:v.target_scope==='SCHOOL'?v.target_school_id:null});toast.success(`Notification distribuée à ${r.recipient_count} destinataire(s)`);await onDone()}catch(e){setError(friendlyError(e))}});return <div className="wizardBackdrop"><form className="accountSecurityDialog platformNotificationDialog" onSubmit={submit} noValidate><div className="modalHead"><div><h3>Notification système</h3><p>Diffusion interne auditable. Aucun SMS ou WhatsApp n’est envoyé par cette action.</p></div><button type="button" onClick={onClose}>×</button></div><FormField label="Titre *" error={f.formState.errors.title?.message}><input {...f.register('title')}/></FormField><FormField label="Niveau *" error={f.formState.errors.severity?.message}><select {...f.register('severity')}><option value="INFO">Information</option><option value="WARNING">Avertissement</option><option value="CRITICAL">Critique</option></select></FormField><FormField label="Cible *" error={f.formState.errors.target_scope?.message}><select {...f.register('target_scope')}><option value="ALL_ACTIVE_SCHOOLS">Toutes les écoles actives</option><option value="SCHOOL">Une école</option></select></FormField>{scope==='SCHOOL'&&<FormField label="École active *" error={f.formState.errors.target_school_id?.message}><select {...f.register('target_school_id')}><option value="">Choisir…</option>{schools.filter(x=>x.status==='ACTIVE').map(x=><option key={x.id} value={x.id}>{x.name} · {x.code}</option>)}</select></FormField>}<FormField label="Message *" error={f.formState.errors.body?.message}><textarea rows={6} {...f.register('body')}/></FormField>{error&&<div className="loginFriendlyError" role="alert">{error}</div>}<div className="modalActions"><button type="button" className="ghost" onClick={onClose}>Annuler</button><button disabled={f.formState.isSubmitting}>{f.formState.isSubmitting?'Diffusion…':'Envoyer la notification'}</button></div></form></div>}

function PlatformSchoolActionDialog({token,action,onClose,onDone}:{token:string;action:{kind:'suspend'|'reactivate'|'admin';school:any};onClose:()=>void;onDone:()=>Promise<void>}){
 const [reason,setReason]=useState(''),[email,setEmail]=useState(''),[fullName,setFullName]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 async function execute(){try{setBusy(true);setError('');if(action.kind==='suspend'){if(reason.trim().length<3)throw new Error('Indiquez le motif de suspension.');await platformSuspendSchool(token,action.school.id,reason.trim());toast.success('École suspendue');}else if(action.kind==='reactivate'){await platformReactivateSchool(token,action.school.id);toast.success('École réactivée');}else{if(!email.trim()||fullName.trim().length<2||password.length<10)throw new Error('Nom, e-mail et mot de passe d’au moins 10 caractères sont obligatoires.');await platformBootstrapAdmin(token,action.school.id,{email:email.trim().toLowerCase(),full_name:fullName.trim(),password});toast.success('Administrateur initial créé');}await onDone()}catch(e){setError(friendlyError(e));setBusy(false)}}
 const title=action.kind==='suspend'?'Suspendre l’école':action.kind==='reactivate'?'Réactiver l’école':'Créer l’administrateur initial';
 return <div className="modalBackdrop" onMouseDown={e=>e.currentTarget===e.target&&onClose()}><div className="platformActionModal" role="dialog" aria-modal="true" aria-label={title}><div className="modalHead"><div><h3>{title}</h3><p><b>{action.school.name}</b> · {action.school.code}</p></div><button className="iconAction" onClick={onClose}>×</button></div>{error&&<div className="error">{error}</div>}{action.kind==='suspend'&&<label>Motif obligatoire<textarea value={reason} onChange={e=>setReason(e.target.value)} rows={4} placeholder="Motif administratif ou technique de la suspension"/></label>}{action.kind==='reactivate'&&<p>La réactivation rendra à nouveau l’école disponible selon ses accès et son état de préparation. L’opération sera auditée.</p>}{action.kind==='admin'&&<div className="platformAdminForm"><label>Nom complet<input value={fullName} onChange={e=>setFullName(e.target.value)} autoFocus/></label><label>Adresse e-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Mot de passe provisoire<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="new-password"/><small>10 caractères minimum. Il sert uniquement à la première connexion : l’administrateur devra choisir son propre mot de passe avant d’accéder à l’école. Si son adresse a déjà un compte EduSync, ce compte est rattaché sans changer son mot de passe. Jamais écrit dans l’audit ni dans la clé d’idempotence.</small></label></div>}<div className="modalFooter"><button className="ghost" onClick={onClose} disabled={busy}>Annuler</button><button className={action.kind==='suspend'?'danger':''} onClick={()=>void execute()} disabled={busy}>{busy?'Traitement…':action.kind==='suspend'?'Confirmer la suspension':action.kind==='reactivate'?'Réactiver':'Créer l’administrateur'}</button></div></div></div>
}

const parameterTabs=[
 ['checkCircle','Mise en service','overview'],['school','École & identité','identity'],['calendar','Années scolaires','years'],['layers','Structure & classes','structure'],['users','Inscriptions','enrollment'],['star','Avantages','benefits'],['receipt','Encaissement','payment'],['receipt','Types de frais','fees'],['tag','Tarifs & barèmes','tariffs'],['box','Contributions en nature','contributions'],['cart','Articles scolaires','products'],
] as const;

type TabKey=typeof parameterTabs[number][2];
const parameterHints:Record<TabKey,string>={overview:'Ce qui est prêt et ce qui reste à faire',identity:'Nom, coordonnées et logo',years:'Préparer, activer, clôturer une année',structure:'Sections et classes ouvertes',enrollment:'Conditions et règles de saisie',benefits:'Famille nombreuse, enfants du personnel',payment:'Acomptes, mois futurs, modes de paiement',fees:'Catalogue des frais',tariffs:'Montants par année et par classe',contributions:'Biens attendus des familles',products:'Articles vendus par l’école'};
const phoneLayout=()=>typeof window!=='undefined'&&window.matchMedia('(max-width:720px)').matches;

function SettingsPage({session}:{session:SavedSchoolSession}){
  const token=session.token;const [tab,setTab]=useState<TabKey>('overview');const [overview,setOverview]=useState<SettingsOverview|null>(null);const [years,setYears]=useState<AcademicYear[]>([]);const [sections,setSections]=useState<SchoolSection[]>([]);const [classes,setClasses]=useState<SchoolClass[]>([]);const [fees,setFees]=useState<FeeType[]>([]);const [tariffs,setTariffs]=useState<Tariff[]>([]);const [contributions,setContributions]=useState<SettingsContribution[]>([]);const [products,setProducts]=useState<SettingsProduct[]>([]);const [refs,setRefs]=useState<ReferenceCatalog|null>(null);const [error,setError]=useState('');
  const can=(p:string)=>session.permissions.includes(p);
  // Phone: the section list is the home of the settings, a section opens as its own screen (Android back returns to the list).
  const [detail,setDetail]=useState(false);
  const open=(key:TabKey)=>{setTab(key);if(phoneLayout()){history.pushState({...(history.state||{}),edusyncSettingsDetail:key},'');setDetail(true);window.scrollTo(0,0)}};
  // A closed dialog may leave its own history entry above the section: unwind until the list entry.
  const back=()=>{if(!history.state?.edusyncSettingsDetail){setDetail(false);return}const unwind=()=>{if(history.state?.edusyncSettingsDetail)history.back();else window.removeEventListener('popstate',unwind)};window.addEventListener('popstate',unwind);history.back()};
  useEffect(()=>{const h=(e:Event)=>{if(!(e as CustomEvent).detail?.edusyncSettingsDetail)setDetail(false)};const r=()=>{if(!phoneLayout())setDetail(false)};window.addEventListener('edusync:android-back',h);window.addEventListener('resize',r);return()=>{window.removeEventListener('edusync:android-back',h);window.removeEventListener('resize',r)}},[]);
  async function refresh(){try{setError('');const safe=<T,>(allowed:boolean,load:()=>Promise<T>,fallback:T)=>allowed?load():Promise.resolve(fallback);const [o,y,s,c,f,t,co,p,r]=await Promise.all([safe(can('settings.school_identity.read'),()=>getSettingsOverview(token),null),safe(can('settings.academic_year.read'),()=>listAcademicYears(token),[]),safe(can('settings.structure.read'),()=>listSections(token),[]),safe(can('settings.structure.read'),()=>listClasses(token),[]),safe(can('settings.fee_types.read'),()=>listFeeTypes(token),[]),safe(can('settings.tariffs.read'),()=>listTariffs(token),[]),safe(can('settings.contributions.read'),()=>listSettingsContributions(token),[]),safe(can('settings.products.read'),()=>listSettingsProducts(token),[]),safe(can('settings.structure.read'),()=>getReferenceCatalog(token),null)]);setOverview(o);setYears(y);setSections(s);setClasses(c);setFees(f);setTariffs(t);setContributions(co);setProducts(p);setRefs(r)}catch(e){setError(friendlyError(e))}}
  useEffect(()=>{void refresh()},[token]);
  return <><div className={`settingsHeader ${detail?'phoneDetailHead':''}`}><div><h2>Centre de configuration</h2><p>Paramétrage progressif : aucune configuration globale ne bloque EduSync.</p></div>{overview&&<div className="readinessBadge"><b>{overview.readiness.percent}%</b><span>Mise en service</span></div>}</div>{error&&<div className="error">{error}</div>}<div className={`settingsLayout ${detail?'phoneDetail':'phoneHome'}`}><div className="settingsNav" aria-label="Sections des paramètres">{parameterTabs.filter(([, ,key])=>key==='overview'||key==='identity'?can('settings.school_identity.read'):key==='years'?can('settings.academic_year.read'):key==='structure'?can('settings.structure.read'):key==='enrollment'?can('settings.enrollment_policy.read'):key==='benefits'?can('settings.benefits.read'):key==='payment'?can('settings.payment_policy.read'):key==='fees'?can('settings.fee_types.read'):key==='tariffs'?can('settings.tariffs.read'):key==='contributions'?can('settings.contributions.read'):key==='products'?can('settings.products.read'):false).map(([icon,label,key])=><button key={key} className={tab===key?'active':''} aria-current={tab===key?'page':undefined} onClick={()=>open(key)}><span aria-hidden="true"><NavGlyph g={icon} size={17}/></span><span className="settingsNavText"><b>{label}</b><small>{parameterHints[key]}</small></span><i className="settingsNavChevron" aria-hidden="true">›</i></button>)}</div><div className="settingsContent"><button type="button" className="settingsBack" onClick={back}><span aria-hidden="true">‹</span> Paramètres</button>
    {tab==='overview'&&<Readiness overview={overview} onOpen={k=>{if(parameterTabs.some(([, ,key])=>key===k))open(k)}}/>} {tab==='identity'&&<IdentitySettings token={token} overview={overview} can={can} onDone={refresh}/>} {tab==='years'&&<Years token={token} years={years} can={can} onDone={refresh}/>} {tab==='structure'&&<Structure token={token} sections={sections} classes={classes} years={years} refs={refs} can={can} onDone={refresh}/>} {tab==='enrollment'&&<><EnrollmentPolicySettings token={token} can={can}/><AdmissionConditionsSettings token={token} years={years} fees={fees} sections={sections} classes={classes} refs={refs} can={can}/></>} {tab==='benefits'&&<BenefitsSettings token={token} years={years} fees={fees} can={can}/>} {tab==='payment'&&<PaymentPolicySettings token={token} can={can}/>} {tab==='fees'&&<Fees token={token} fees={fees} refs={refs} can={can} onDone={refresh}/>} {tab==='tariffs'&&<TariffsSettings token={token} tariffs={tariffs} years={years} fees={fees} classes={classes} sections={sections} refs={refs} can={can} onDone={refresh}/>} {tab==='contributions'&&<ContributionsSettings token={token} items={contributions} can={can} onDone={refresh}/>} {tab==='products'&&<ProductsSettings token={token} items={products} can={can} onDone={refresh}/>}
  </div></div></>
}

// Guided start: each item that is not ready opens the section that settles it; the first one is proposed as the next step.
const READINESS_TARGET:Record<string,TabKey>={IDENTITY:'identity',ACADEMIC_YEAR:'years',STRUCTURE:'structure',FEE_TYPES:'fees',TARIFFS:'tariffs'};
function Readiness({overview,onOpen}:{overview:SettingsOverview|null;onOpen:(k:TabKey)=>void}){if(!overview)return <Loading/>;const next=overview.readiness.items.find(i=>i.state!=='READY'&&i.state!=='NOT_APPLICABLE'&&READINESS_TARGET[i.code]);return <Panel title="École immédiatement exploitable" subtitle="Le pourcentage est informatif. Seule l’action qui manque d’un prérequis est bloquée.">{next?<div className="nextStep"><span>Prochaine étape</span><b>{next.label}</b><p>{next.detail}</p><button type="button" className="primaryBtn" onClick={()=>onOpen(READINESS_TARGET[next.code])}>Continuer</button></div>:<div className="nextStep done"><span>Mise en service</span><b>L’essentiel est prêt.</b><p>Vous pouvez compléter les autres paramètres à tout moment.</p></div>}<div className="readinessGrid">{overview.readiness.items.map(i=><div className="readinessItem" key={i.code}><em className={`status ${i.state.toLowerCase()}`}>{i.state==='READY'?'Prêt':i.state==='NOT_APPLICABLE'?'Non applicable':i.state==='TO_CONFIRM'?'À confirmer':'À compléter'}</em><b>{i.label}</b><p>{i.detail}</p>{i.blocking_only_for.length>0&&<small>Nécessaire pour : {i.blocking_only_for.map((c:string)=>BLOCKING_LABEL[c]??c.toLowerCase()).join(' · ')}</small>}{i.state!=='READY'&&READINESS_TARGET[i.code]&&<button type="button" className="linkBtn" onClick={()=>onOpen(READINESS_TARGET[i.code])}>Ouvrir <span aria-hidden="true">›</span></button>}</div>)}</div></Panel>}

function Years({token,years,can,onDone}:{token:string;years:AcademicYear[];can:(x:string)=>boolean;onDone:()=>Promise<void>}){
  const [error,setError]=useState('');const [creating,setCreating]=useState(false);const [busy,setBusy]=useState('');const next=useMemo(()=>suggestNextYear(years.map(y=>y.code)),[years]);
  const yearSchema=z.object({code:z.string().trim().min(4,'Indiquez le code de l’année, par exemple 2027-2028.'),label:z.string().trim().min(4,'Indiquez le libellé affiché, par exemple 2027-2028.'),start_date:z.string().min(1,'Choisissez la date de rentrée.'),end_date:z.string().min(1,'Choisissez la date de fin d’année.')}).refine(v=>v.end_date>v.start_date,{message:'La fin d’année doit venir après la rentrée.',path:['end_date']}).refine(v=>!years.some(y=>y.code.toLowerCase()===v.code.trim().toLowerCase()),{message:'Cette année existe déjà.',path:['code']});type YearForm=z.infer<typeof yearSchema>;const yearForm=useForm<YearForm>({resolver:zodResolver(yearSchema),values:next,...formDefaults});
  const create=yearForm.handleSubmit(async form=>{try{setError('');await createAcademicYear(token,form);toast.success(`Année ${form.label} préparée`);setCreating(false);await onDone()}catch(e){setError(friendlyError(e))}});
  const active=years.find(y=>y.status==='ACTIVE');
  const confirmText:Record<'activate'|'close'|'archive'|'reopen',(y:AcademicYear)=>{title:string;message:string;confirmLabel:string;danger?:boolean}>={
    activate:y=>({title:`Activer ${y.label} ?`,message:'Elle devient l’année en cours de l’école : les écrans et les nouvelles opérations s’y rattachent.',confirmLabel:'Activer l’année'}),
    close:y=>({title:`Clôturer ${y.label} ?`,message:'Elle ne sera plus l’année en cours. Son historique reste consultable et elle pourra être rouverte si nécessaire.',confirmLabel:'Clôturer l’année',danger:true}),
    archive:y=>({title:`Archiver ${y.label} ?`,message:'L’année passe aux archives. Rien n’est supprimé : elle reste consultable et peut être rouverte.',confirmLabel:'Archiver'}),
    reopen:y=>({title:`Rouvrir ${y.label} ?`,message:'Elle repasse en préparation. Il faudra l’activer de nouveau pour qu’elle redevienne l’année en cours.',confirmLabel:'Rouvrir'}),
  };
  async function act(y:AcademicYear,action:'activate'|'close'|'archive'|'reopen'){if(!await confirmAction(confirmText[action](y)))return;try{setBusy(y.id);setError('');if(action==='activate')await activateAcademicYear(token,y);else await transitionAcademicYear(token,y,action);toast.success(action==='activate'?`${y.label} est l’année en cours`:action==='close'?`${y.label} clôturée`:action==='archive'?`${y.label} archivée`:`${y.label} rouverte`);await onDone()}catch(e){setError(friendlyError(e))}finally{setBusy('')}}
  return <Panel title="Années scolaires" subtitle="Une année est préparée, mise en cours, clôturée puis archivée. Une année rouverte repasse en préparation.">{error&&<div className="error" role="alert">{error}</div>}
    {years.length===0&&<div className="emptyGuide"><b>Aucune année scolaire</b><p>Préparez la première année, puis activez-la : les classes, les tarifs et les inscriptions s’y rattachent.</p></div>}
    {can('settings.academic_year.create')&&(creating?<form className="gridForm validatedGridForm yearCreate" onSubmit={create} noValidate><FormField label="Code *" error={yearForm.formState.errors.code?.message}><input autoComplete="off" {...yearForm.register('code')}/></FormField><FormField label="Libellé *" error={yearForm.formState.errors.label?.message}><input autoComplete="off" {...yearForm.register('label')}/></FormField><FormField label="Rentrée *" error={yearForm.formState.errors.start_date?.message}><input type="date" {...yearForm.register('start_date')}/></FormField><FormField label="Fin d’année *" error={yearForm.formState.errors.end_date?.message}><input type="date" {...yearForm.register('end_date')}/></FormField><div className="formActions"><button type="button" className="ghost" onClick={()=>setCreating(false)}>Annuler</button><button className="primaryBtn" disabled={yearForm.formState.isSubmitting}>Préparer l’année</button></div></form>:<button type="button" className="softBtn addLine" onClick={()=>setCreating(true)}>+ Préparer une nouvelle année <small>proposition : {next.label}</small></button>)}
    <div className="cardsList yearList">{years.map(y=><article key={y.id} className={y.status==='ACTIVE'?'current':''}><div><b>{y.label}</b><small>{formatDate(y.start_date)} → {formatDate(y.end_date)}</small></div><em className={`pill ${y.status==='ACTIVE'?'ready':''}`}>{yearStatusLabel(y.status)}</em><div className="rowActions">{y.status==='PREPARED'&&can('settings.academic_year.activate')&&(active?<small className="hint">Clôturez d’abord {active.label} pour l’activer.</small>:<button disabled={busy===y.id} onClick={()=>void act(y,'activate')}>Activer</button>)}{y.status==='ACTIVE'&&can('settings.academic_year.close')&&<button className="dangerSoft" disabled={busy===y.id} onClick={()=>void act(y,'close')}>Clôturer</button>}{y.status==='CLOSED'&&can('settings.academic_year.archive')&&<button disabled={busy===y.id} onClick={()=>void act(y,'archive')}>Archiver</button>}{(y.status==='CLOSED'||y.status==='ARCHIVED')&&can('settings.academic_year.reopen')&&<button className="ghost" disabled={busy===y.id} onClick={()=>void act(y,'reopen')}>Rouvrir</button>}</div></article>)}</div></Panel>
}

function Structure({token,sections,classes,years,refs,can,onDone}:{token:string;sections:SchoolSection[];classes:SchoolClass[];years:AcademicYear[];refs:ReferenceCatalog|null;can:(x:string)=>boolean;onDone:()=>Promise<void>}){
  const [error,setError]=useState('');const [sectionId,setSectionId]=useState('');const [referenceCode,setReferenceCode]=useState('');const [optionId,setOptionId]=useState('');const [options,setOptions]=useState<SchoolOption[]>([]);const [optionDraft,setOptionDraft]=useState<{section_id:string;label:string}|null>(null);
  async function loadOptions(){try{setOptions(await listOptions(token))}catch{setOptions([])}}
  useEffect(()=>{void loadOptions()},[token]);
  const optionCode=(label:string)=>label.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,48);
  async function saveOption(o:{section_id:string;code:string;label:string;enabled:boolean;expected_version?:number|null;tariff_group_code?:string|null},done:string){try{setError('');await putOption(token,o);toast.success(done);setOptionDraft(null);await loadOptions()}catch(e){setError(friendlyError(e))}}
  async function setOptionGroup(o:SchoolOption,group:string){if(!group)return;await saveOption({section_id:o.section_id,code:o.code,label:o.label,enabled:o.enabled,expected_version:o.version,tariff_group_code:group},`${o.label} : ${TARIFF_GROUPS.find(g=>g[0]===group)?.[1]}`)}
  async function toggleOption(o:SchoolOption){if(o.enabled&&!await confirmAction({title:`Désactiver l’option ${o.label} ?`,message:'Rien n’est supprimé : les classes déjà rattachées la conservent. Elle n’est plus proposée pour ouvrir de nouvelles classes.',confirmLabel:'Désactiver',danger:true}))return;await saveOption({section_id:o.section_id,code:o.code,label:o.label,enabled:!o.enabled,expected_version:o.version},o.enabled?`Option ${o.label} désactivée`:`Option ${o.label} réactivée`)}
  const active=years.find(y=>y.status==='ACTIVE')??years.find(y=>y.status==='PREPARED');
  async function addSection(code:string,label:string){try{await putSection(token,{code,label,enabled:true});await onDone()}catch(e){setError(friendlyError(e))}}
  async function rename(c:SchoolClass){const label=await promptText({title:`Renommer ${c.label}`,message:'Le libellé affiché change partout ; les élèves, l’historique et le statut de la classe ne changent pas.',label:'Nouveau libellé',confirmLabel:'Renommer',minLength:2});if(!label||label===c.label)return;try{setError('');await updateClass(token,c,{code:c.code,label});toast.success(`Classe renommée : ${label}`);await onDone()}catch(e){setError(friendlyError(e))}}
  // Desktop set_class_status: pause keeps the students (counted, visible, attached); archive only once the class is empty.
  async function changeStatus(c:SchoolClass,status:'ACTIVE'|'INACTIVE'|'ARCHIVED'){const n=c.student_count??0;const ask=status==='INACTIVE'?{title:`Mettre ${c.label} en pause ?`,message:`${n>0?`Ses ${n} élève(s) restent inscrits, comptés dans les effectifs et visibles. `:''}La classe n’est plus proposée pour de nouvelles inscriptions ni comme destination d’un changement de classe. Elle pourra être réactivée.`,confirmLabel:'Mettre en pause',danger:true}:status==='ARCHIVED'?{title:`Archiver ${c.label} ?`,message:'La classe est vide. Archivée, elle reste dans l’historique mais ne pourra plus être modifiée ni réactivée.',confirmLabel:'Archiver',danger:true}:{title:`Réactiver ${c.label} ?`,message:'La classe est de nouveau proposée pour les inscriptions et les changements de classe.',confirmLabel:'Réactiver'};if(!await confirmAction(ask))return;try{setError('');await setClassStatus(token,c,status);toast.success(status==='INACTIVE'?`${c.label} en pause`:status==='ARCHIVED'?`${c.label} archivée`:`${c.label} réactivée`);await onDone()}catch(e){setError(friendlyError(e))}}
  async function addClass(){try{const section=sections.find(x=>x.id===sectionId);const ref=refs?.classes.find(x=>x.code===referenceCode);if(!active||!section||!ref)throw new Error('Choisissez une année, une section et une classe de référence');if(ref.section_code!==section.code)throw new Error('La classe de référence ne correspond pas à la section choisie');await createClass(token,{academic_year_id:active.id,section_id:section.id,reference_code:ref.code,code:ref.code,label:ref.label,option_id:optionId||null});setReferenceCode('');setOptionId('');await onDone()}catch(e){setError(friendlyError(e))}}
  const existing=new Set(sections.map(s=>s.code));const classCodes=new Set(classes.filter(c=>c.academic_year_id===active?.id).map(c=>c.code));
  return <Panel title="Structure & classes" subtitle="Le référentiel RDC propose la structure, mais l’école confirme seulement ce qu’elle organise réellement.">{error&&<div className="error">{error}</div>}<div className="suggestions">{refs?.sections.map(r=><button disabled={existing.has(r.code)||!can('settings.sections.manage')} key={r.code} onClick={()=>void addSection(r.code,r.label)}>{existing.has(r.code)?'✓ ': '+ '}{r.label}</button>)}</div>{sections.length===0&&<div className="emptyGuide"><b>Aucune section</b><p>Touchez les sections que l’école organise réellement ci-dessus. Vous ouvrirez ensuite les classes de chaque section.</p></div>}<div className="cardsList sectionList">{sections.map(s=>{const opts=options.filter(o=>o.section_id===s.id);return <article key={s.id}><div><b>{s.label}</b><small>{classes.filter(c=>c.section_id===s.id&&c.academic_year_id===active?.id&&c.enabled).length} classe(s) ouverte(s){active?` en ${active.label}`:''}</small>{(opts.length>0||can('settings.options.manage'))&&<div className="optionChips" aria-label={`Options de ${s.label}`}>{opts.map(o=><span className="optionItem" key={o.id}><button type="button" className={o.enabled?'on':'off'} disabled={!can('settings.options.manage')} onClick={()=>void toggleOption(o)} title={o.enabled?'Désactiver cette option':'Réactiver cette option'}>{o.label}{o.enabled?'':' · désactivée'}</button><select aria-label={`Groupe tarifaire de ${o.label}`} value={o.tariff_group_code??''} disabled={!can('settings.option_tariff_group.manage')} onChange={e=>void setOptionGroup(o,e.target.value)}><option value="">Groupe tarifaire…</option>{TARIFF_GROUPS.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></span>)}{can('settings.options.manage')&&s.enabled&&(optionDraft?.section_id===s.id?<form className="optionDraft" onSubmit={e=>{e.preventDefault();const label=optionDraft.label.trim();const code=optionCode(label);if(label.length<2||!code){setError('Indiquez le nom de l’option, par exemple Commerciale et gestion.');return}if(opts.some(o=>o.code===code)){setError('Cette option existe déjà dans la section.');return}void saveOption({section_id:s.id,code,label,enabled:true},`Option ${label} ajoutée`)}}><input aria-label="Nom de l’option" autoFocus placeholder="Nom de l’option" value={optionDraft.label} onChange={e=>setOptionDraft({section_id:s.id,label:e.target.value})}/><button className="primaryBtn">Ajouter</button><button type="button" className="ghost" onClick={()=>setOptionDraft(null)}>Annuler</button></form>:<button type="button" className="addChip" onClick={()=>setOptionDraft({section_id:s.id,label:''})}>+ Option</button>)}</div>}</div><em className={`pill ${s.enabled?'ready':''}`}>{s.enabled?'Active':'Inactive'}</em></article>})}</div>
    {!active&&<div className="emptyGuide"><b>Aucune année préparée ou en cours</b><p>Préparez une année scolaire avant d’ouvrir des classes : chaque classe appartient à une année.</p></div>}
    {can('settings.classes.create')&&active&&sections.length>0&&<div className="gridForm classCreate"><FormField label="Section"><select value={sectionId} onChange={e=>{setSectionId(e.target.value);setReferenceCode('')}}><option value="">Choisir la section…</option>{sections.filter(s=>s.enabled).map(s=><option key={s.id} value={s.id}>{s.label}</option>)}</select></FormField><FormField label="Classe à ouvrir"><select value={referenceCode} disabled={!sectionId} onChange={e=>setReferenceCode(e.target.value)}><option value="">{sectionId?'Choisir la classe…':'Choisissez d’abord la section'}</option>{refs?.classes.filter(r=>!classCodes.has(r.code)&&r.section_code===sections.find(x=>x.id===sectionId)?.code).map(r=><option key={r.code} value={r.code}>{r.label}</option>)}</select></FormField>{options.some(o=>o.section_id===sectionId&&o.enabled)&&<FormField label="Option (facultatif)"><select value={optionId} onChange={e=>setOptionId(e.target.value)}><option value="">Sans option</option>{options.filter(o=>o.section_id===sectionId&&o.enabled).map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></FormField>}<button type="button" className="primaryBtn" disabled={!referenceCode} onClick={()=>void addClass()}>Ouvrir la classe en {active.label}</button></div>}
    {classes.length>0&&<div className="classGroups">{sections.map(s=>{const list=classes.filter(c=>c.section_id===s.id);if(!list.length)return null;return <section key={s.id} aria-label={s.label}><h4>{s.label}</h4><ul className="classList">{list.map(c=>{const st=c.status??(c.enabled?'ACTIVE':'INACTIVE');const n=c.student_count??0;const locked=c.academic_year_status==='CLOSED'||c.academic_year_status==='ARCHIVED';return <li key={c.id} className={st==='ACTIVE'?'':'off'}><div><b>{c.label}</b><small>{c.academic_year_code??''} · {n} élève(s){st==='INACTIVE'?' · en pause':st==='ARCHIVED'?' · archivée':''}</small></div>{!locked&&st!=='ARCHIVED'&&(can('settings.classes.activate')||can('settings.classes.rename'))&&<div className="classActions">{can('settings.classes.rename')&&<button type="button" className="ghost" onClick={()=>void rename(c)}>Renommer</button>}{can('settings.classes.activate')&&<>{st==='ACTIVE'?<button type="button" className="ghost" onClick={()=>void changeStatus(c,'INACTIVE')}>Mettre en pause</button>:<button type="button" className="softBtn" onClick={()=>void changeStatus(c,'ACTIVE')}>Réactiver</button>}{n===0&&<button type="button" className="ghost dangerText" onClick={()=>void changeStatus(c,'ARCHIVED')}>Archiver</button>}</>}</div>}</li>})}</ul></section>})}</div>}</Panel>
}

function Fees({token,fees,refs,can,onDone}:{token:string;fees:FeeType[];refs:ReferenceCatalog|null;can:(x:string)=>boolean;onDone:()=>Promise<void>}){const [error,setError]=useState('');const existing=new Set(fees.map(f=>f.code));async function add(f:ReferenceCatalog['fee_types'][number]){try{await createFeeType(token,{code:f.code,label:f.label,periodicity:f.periodicity,default_currency:f.default_currency});await onDone()}catch(e){setError(friendlyError(e))}}return <Panel title="Types de frais" subtitle="Le catalogue de référence n’engendre aucune dette tant qu’un tarif réel n’est pas confirmé.">{error&&<div className="error">{error}</div>}<div className="suggestions">{refs?.fee_types.map(f=><button key={f.code} disabled={existing.has(f.code)||!can('settings.fee_types.manage')} onClick={()=>void add(f)}>{existing.has(f.code)?'✓ ': '+ '}{f.label}</button>)}</div><div className="cardsList">{fees.map(f=><article key={f.id}><div><b>{f.label}</b><small>{PERIODICITY_LABEL[f.periodicity]??f.periodicity} · {f.default_currency}</small></div><em className="pill ready">Actif</em></article>)}</div></Panel>}

function IdentitySettings({token,overview,can,onDone}:{token:string;overview:SettingsOverview|null;can:(x:string)=>boolean;onDone:()=>Promise<void>}){const school=overview?.school;const schema=z.object({name:z.string().trim().min(2,'Nom obligatoire.'),email:z.string().trim().email('Adresse e-mail incomplète, par exemple direction@ecole.cd.').or(z.literal('')),phone:z.string().trim().regex(/^[+0-9 ()-]*$/,'Seuls les chiffres, espaces et le signe + sont acceptés.'),logo_url:z.string(),address:z.string(),city:z.string(),province:z.string()});type F=z.infer<typeof schema>;const form=useForm<F>({resolver:zodResolver(schema),values:{name:school?.name??'',email:school?.email??'',phone:school?.phone??'',logo_url:school?.logo_url??'',address:school?.address??'',city:school?.city??'',province:school?.province??''},...formDefaults});const [error,setError]=useState('');const save=form.handleSubmit(async v=>{if(!school)return;try{setError('');await updateSchoolIdentity(token,{name:v.name,email:v.email||null,phone:v.phone||null,logo_url:v.logo_url||null,address:v.address||null,city:v.city||null,province:v.province||null},school.version);toast.success('Identité de l’école enregistrée');await onDone()}catch(e){setError(friendlyError(e))}});return <Panel title="École & identité" subtitle="Coordonnées institutionnelles utilisées par l’interface et les documents.">{error&&<div className="error">{error}</div>}<LogoField token={token} canUpload={can('settings.documents.manage')}/><form className="settingsEditorGrid identityForm" onSubmit={save} noValidate><fieldset disabled={!can('settings.school_identity.update')}><legend>Établissement</legend><FormField label="Nom de l’école *" error={form.formState.errors.name?.message}><input autoComplete="organization" {...form.register('name')}/></FormField></fieldset><fieldset disabled={!can('settings.school_identity.update')}><legend>Contact</legend><FormField label="Téléphone" error={form.formState.errors.phone?.message}><input type="tel" inputMode="tel" autoComplete="tel" placeholder="+243 …" {...form.register('phone')}/></FormField><FormField label="E-mail" error={form.formState.errors.email?.message}><input type="email" inputMode="email" autoComplete="email" {...form.register('email')}/></FormField></fieldset><fieldset disabled={!can('settings.school_identity.update')}><legend>Adresse</legend><FormField label="Adresse"><input autoComplete="street-address" {...form.register('address')}/></FormField><FormField label="Ville"><input autoComplete="address-level2" {...form.register('city')}/></FormField><FormField label="Province"><input autoComplete="address-level1" {...form.register('province')}/></FormField></fieldset>{can('settings.school_identity.update')&&<div className="stickyActions"><button className="primaryBtn" disabled={form.formState.isSubmitting||!form.formState.isDirty}>{form.formState.isSubmitting?'Enregistrement…':'Enregistrer'}</button></div>}</form></Panel>}

// Enrollment policy as enforced by the schooling module (required fields, guardian rules). The five terrain fields stay mandatory.
const ENROLLMENT_FIXED:[string,string][]=[['last_name','Nom'],['middle_name','Post-nom'],['first_name','Prénom'],['gender','Sexe'],['class_id','Classe']];
const ENROLLMENT_OPTIONAL:[string,string][]=[['birth_date','Date de naissance'],['birth_place','Lieu de naissance'],['nationality','Nationalité'],['address','Adresse'],['previous_school','École de provenance']];
function EnrollmentPolicySettings({token,can}:{token:string;can:(x:string)=>boolean}){
  const [policy,setPolicy]=useState<{version:number;payload:Record<string,unknown>}|null|undefined>(undefined);const [extra,setExtra]=useState<string[]>([]);const [guardian,setGuardian]=useState(false);const [phone,setPhone]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const editable=can('settings.enrollment_policy.manage');
  async function load(){try{setError('');const r=await getPolicy(token,'ENROLLMENT');setPolicy(r);const pl=(r?.payload??{}) as Record<string,unknown>;const req=Array.isArray(pl.required_student_fields)?pl.required_student_fields as string[]:[];setExtra(ENROLLMENT_OPTIONAL.map(([k])=>k).filter(k=>req.includes(k)));setGuardian(!!pl.guardian_required_at_enrollment);setPhone(!!pl.guardian_phone_required)}catch(e){setError(friendlyError(e))}}
  useEffect(()=>{void load()},[token]);
  async function save(e:React.FormEvent){e.preventDefault();try{setBusy(true);setError('');await putPolicy(token,'ENROLLMENT',{payload:{...(policy?.payload??{}),required_student_fields:[...ENROLLMENT_FIXED.map(([k])=>k),...extra],guardian_required_at_enrollment:guardian,guardian_phone_required:phone},status:'ACTIVE',expected_version:policy?.version??null});toast.success('Règles d’inscription enregistrées : elles s’appliquent aux prochaines inscriptions.');await load()}catch(e){setError(friendlyError(e))}finally{setBusy(false)}}
  if(policy===undefined&&!error)return <Loading/>;
  return <Panel title="Règles de saisie à l’inscription" subtitle="Informations que l’école exige pour inscrire un élève (réglage propre au Web). Les inscriptions déjà faites ne sont pas modifiées.">{error&&<div className="error" role="alert">{error}</div>}
    <form className="policyForm" onSubmit={save}><fieldset disabled={!editable||busy}><legend>Informations de l’élève</legend><p className="policyHint">Toujours obligatoires : {ENROLLMENT_FIXED.map(([,l])=>l).join(', ')}.</p>
      {ENROLLMENT_OPTIONAL.map(([k,l])=><label key={k} className="switchRow"><span>{l}<small>{extra.includes(k)?'Obligatoire':'Facultatif'}</small></span><input type="checkbox" role="switch" checked={extra.includes(k)} onChange={e=>setExtra(x=>e.target.checked?[...x,k]:x.filter(y=>y!==k))}/></label>)}</fieldset>
      <fieldset disabled={!editable||busy}><legend>Responsable</legend>
      <label className="switchRow"><span>Responsable exigé à l’inscription<small>Sans responsable ni foyer existant, l’inscription est refusée.</small></span><input type="checkbox" role="switch" checked={guardian} onChange={e=>setGuardian(e.target.checked)}/></label>
      <label className="switchRow"><span>Téléphone du responsable exigé<small>Quand un responsable est saisi, son téléphone devient obligatoire.</small></span><input type="checkbox" role="switch" checked={phone} onChange={e=>setPhone(e.target.checked)}/></label></fieldset>
      {editable&&<div className="stickyActions"><button className="primaryBtn" disabled={busy}>{busy?'Enregistrement…':'Enregistrer les règles'}</button></div>}
      {!editable&&<p className="policyHint">Lecture seule : la modification demande la permission de gérer la politique d’inscription.</p>}
    </form></Panel>
}

// The logo is a stored, verified image (PNG/JPEG ≤ 1 Mo, checked by its bytes server-side), never a free URL.
function LogoField({token,canUpload}:{token:string;canUpload:boolean}){
  const [src,setSrc]=useState<string|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const input=React.useRef<HTMLInputElement>(null);
  async function load(){try{const b=await schoolLogoBlob(token);setSrc(old=>{if(old)URL.revokeObjectURL(old);return b?URL.createObjectURL(b):null})}catch{setSrc(null)}}
  useEffect(()=>{void load();return()=>setSrc(old=>{if(old)URL.revokeObjectURL(old);return null})},[token]);
  async function pick(f:File|undefined){if(!f)return;setError('');if(!['image/png','image/jpeg'].includes(f.type)){setError('Choisissez une image PNG ou JPEG.');return}if(f.size>1024*1024){setError('Le logo dépasse 1 Mo : réduisez l’image puis réessayez.');return}try{setBusy(true);await uploadSchoolLogo(token,f);toast.success('Logo enregistré : il apparaîtra sur les prochains documents.');await load()}catch(e){setError(friendlyError(e))}finally{setBusy(false);if(input.current)input.current.value=''}}
  return <div className="logoField"><div className="logoPreview">{src?<img src={src} alt="Logo actuel de l’école"/>:<span aria-hidden="true"><NavGlyph g="school" size={26}/></span>}</div><div><b>Logo de l’école</b><small>{src?'Utilisé sur les documents imprimés.':'Aucun logo : les documents s’impriment sans logo.'} PNG ou JPEG, 1 Mo maximum.</small>{error&&<span className="fieldError" role="alert">{error}</span>}</div>{canUpload&&<><input ref={input} type="file" accept="image/png,image/jpeg" hidden onChange={e=>void pick(e.target.files?.[0])}/><button type="button" className="softBtn" disabled={busy} onClick={()=>input.current?.click()}>{busy?'Envoi…':src?'Remplacer':'Ajouter un logo'}</button></>}</div>
}


function ContributionsSettings({token,items,can,onDone}:{token:string;items:SettingsContribution[];can:(x:string)=>boolean;onDone:()=>Promise<void>}){const schema=z.object({code:z.string().trim().min(2),label:z.string().trim().min(2),unit:z.string().trim().min(1)});type F=z.infer<typeof schema>;const form=useForm<F>({resolver:zodResolver(schema),defaultValues:{code:'',label:'',unit:'unité'},...formDefaults});const save=form.handleSubmit(async v=>{await createSettingsContribution(token,v);form.reset({code:'',label:'',unit:'unité'});toast.success('Contribution créée');await onDone()});return <Panel title="Contributions en nature" subtitle="Catalogue des fournitures ou biens attendus; les dépôts réels restent dans Effectifs & dépôts.">{can('settings.contributions.manage')&&<form className="settingsEditorGrid compact" onSubmit={save}><FormField label="Code"><input {...form.register('code')}/></FormField><FormField label="Libellé"><input {...form.register('label')}/></FormField><FormField label="Unité"><input {...form.register('unit')}/></FormField><button className="primaryBtn">Ajouter</button></form>}<div className="cardsList">{items.map(x=><article key={x.id}><div><b>{x.label}</b><small>{x.code} · {x.unit}</small></div><em className={`pill ${x.enabled?'ready':''}`}>{x.enabled?'Actif':'Inactif'}</em></article>)}</div></Panel>}

function ProductsSettings({token,items,can,onDone}:{token:string;items:SettingsProduct[];can:(x:string)=>boolean;onDone:()=>Promise<void>}){const schema=z.object({code:z.string().trim().min(2),label:z.string().trim().min(2),currency:z.enum(['CDF','USD']),unit_price:z.string().refine(v=>Number(v)>0),stock_tracking:z.boolean()});type F=z.infer<typeof schema>;const form=useForm<F>({resolver:zodResolver(schema),defaultValues:{code:'',label:'',currency:'CDF',unit_price:'',stock_tracking:true},...formDefaults});const save=form.handleSubmit(async v=>{await createSettingsProduct(token,v);form.reset({code:'',label:'',currency:'CDF',unit_price:'',stock_tracking:true});toast.success('Article créé');await onDone()});return <Panel title="Articles scolaires" subtitle="Catalogue utilisé par la vente d’articles; le suivi de stock reste relié à l’Intendance.">{can('settings.products.manage')&&<form className="settingsEditorGrid compact" onSubmit={save}><FormField label="Code"><input {...form.register('code')}/></FormField><FormField label="Article"><input {...form.register('label')}/></FormField><FormField label="Devise"><select {...form.register('currency')}><option>CDF</option><option>USD</option></select></FormField><FormField label="Prix"><input inputMode="decimal" {...form.register('unit_price')}/></FormField><label className="checkField"><input type="checkbox" {...form.register('stock_tracking')}/> Suivre le stock</label><button className="primaryBtn">Ajouter</button></form>}<div className="cardsList">{items.map(x=><article key={x.id}><div><b>{x.label}</b><small>{formatMoney(x.unit_price,x.currency)}{x.stock_tracking?' · stock suivi':''}</small></div><em className={`pill ${x.enabled?'ready':''}`}>{x.enabled?'Actif':'Inactif'}</em></article>)}</div></Panel>}

function ModuleLoader(){return <div className="moduleLoader"><div className="loaderLine"><i/></div><b>Ouverture du module…</b><span>Préparation de votre espace de travail</span></div>}
function Loading(){return <ModuleLoader/>}
function Kpi({icon,value,label}:{icon:string;value:React.ReactNode;label:string}){return <article><span aria-hidden="true"><NavGlyph g={icon} size={20}/></span><b>{value}</b><small>{label}</small></article>}
function Panel({title,subtitle,children}:{title:string;subtitle?:string;children:React.ReactNode}){return <section className="panel"><div className="panelHead"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div></div>{children}</section>}
function PlatformCollaboratorDialog({user,onClose,onConfirm}:{user:any;onClose:()=>void;onConfirm:(reason:string)=>Promise<void>}){const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const revoke=Boolean(user.collaborator_platform);return <div className="modalBackdrop" onMouseDown={e=>e.currentTarget===e.target&&onClose()}><section className="platformActionModal" role="dialog" aria-modal="true" aria-label="Collaboration plateforme"><div className="modalHead"><div><h3>{revoke?'Retirer la collaboration':'Donner un accès collaborateur'}</h3><p>{user.full_name} · {user.email}</p></div><button className="ghost" onClick={onClose}>×</button></div><p className="collaboratorDoctrine">Le Collaborateur plateforme peut consulter les écoles, l’audit et les diagnostics. Il ne peut ni créer/suspendre une école, ni créer un administrateur, ni gérer d’autres collaborateurs.</p><label>Motif *<textarea value={reason} onChange={e=>setReason(e.target.value)} rows={3}/></label><div className="modalActions"><button className="ghost" onClick={onClose}>Annuler</button><button disabled={busy||reason.trim().length<5} onClick={async()=>{setBusy(true);try{await onConfirm(reason.trim())}finally{setBusy(false)}}}>{revoke?'Retirer':'Accorder'}</button></div></section></div>}

type PlatformUser={full_name:string;email:string};
function Shell({title,subtitle,onLogout,nav,children,user,token,roleLabel}:{title:string;subtitle:string;token?:string;roleLabel?:string;onLogout:()=>void;nav:[string,string,boolean,(()=>void)?,string?][];children:React.ReactNode;user:PlatformUser}){const [profile,setProfile]=useState(false);const [security,setSecurity]=useState(false);const shellNav:ShellNavItem[]=nav.map(([icon,label,active,go,key],i)=>({key:key||label,label,icon,active,onSelect:()=>go?.(),primary:i<3,shortLabel:label.split(' ')[0]}));const context=`Atelier Pro · ${roleLabel||'Équipe plateforme'}`;const account:ShellAccount={name:user.full_name||'Membre de l’équipe',email:user.email,context,items:[{key:'profile',label:'Mon profil',icon:'user',onSelect:()=>setProfile(true)},{key:'security',label:'Sécurité et appareils',icon:'shield',onSelect:()=>setSecurity(true)},{key:'logout',label:'Se déconnecter',icon:'logout',onSelect:onLogout,danger:true}]};return <AppShell orgLabel="Atelier Pro" orgCode="Administration de la plateforme" mobileTitle="Atelier Pro" nav={shellNav} title={nav.find(n=>n[2])?.[1]||title} context={subtitle} tools={<>{token&&<NotificationBell token={token} canDismiss scope="platform"/>}<StatusChip/></>} account={account}>{children}{profile&&<ProfileDialog name={account.name} email={user.email} context={context} onClose={()=>setProfile(false)}/>}{security&&token&&<SecurityDialog platform token={token} onClose={()=>setSecurity(false)} onPasswordChanged={onLogout}/>}</AppShell>}

// POINT 4D frozen navigation contract: ['settings','personnel','students','headcounts','home']
function SchoolApp({session,onLogout}:{session:SavedSchoolSession;onLogout:()=>void}){const [dialog,setDialog]=useState<''|'profile'|'security'>('');const [module,setModule]=useState('home');const goModule=(next:string)=>{if(next!==module)pushMobileScreen('school',next);setModule(next)};useEffect(()=>{replaceMobileRoot('school','home');const h=(e:Event)=>{const d=(e as CustomEvent).detail;if(d?.edusyncScope==='school'&&d.edusyncScreen)setModule(d.edusyncScreen)};window.addEventListener('edusync:android-back',h);return()=>window.removeEventListener('edusync:android-back',h)},[]);const [shellYears,setShellYears]=useState<AcademicYear[]>([]);const [selectedYearId,setSelectedYearId]=useState('');useEffect(()=>{let alive=true;listYearSelector(session.token).then(years=>{if(!alive)return;setShellYears(years);const saved=localStorage.getItem(`edusync.year.${session.school.id}`);const selected=(saved&&years.some(y=>y.id===saved)?saved:years.find(y=>y.status==='ACTIVE')?.id)||years[0]?.id||'';setSelectedYearId(selected)}).catch(()=>{if(alive)setShellYears([])});return()=>{alive=false}},[session.token,session.school.id]);function selectShellYear(id:string){setSelectedYearId(id);if(id)localStorage.setItem(`edusync.year.${session.school.id}`,id)}const selectedYear=shellYears.find(y=>y.id===selectedYearId);
  const nav=[['home','Accueil','home'],['settings','Paramètres','settings'],['users','Personnel','personnel'],['students','Élèves & inscriptions','students'],['chart','Effectifs & dépôts','headcounts'],['finance','Centre financier','finance'],['folder','Documents','documents'],['box','Intendance','stewardship'],['sync','Synchronisation','sync'],['lock','Accès & rôles','access']] as const;
  const prefixes:Record<string,string[]>={settings:['settings.'],personnel:['personnel.'],students:['students.','families.','enrollments.'],headcounts:['headcounts.'],finance:['finance.','contributions.'],documents:['documents.','students.directory.','families.directory.','personnel.directory.','headcounts.export','headcounts.print','finance.views.','finance.reports.'],stewardship:['inventory.'],sync:['sync.'],access:['access.roles.read','audit.school.read']};
  const canOpenModule=(key:string)=>key==='home'||(prefixes[key]??[]).some(prefix=>session.permissions.some(p=>p.startsWith(prefix)));
  const visibleNav=nav.filter(([, ,key])=>canOpenModule(key));
  const currentLabel=visibleNav.find(([, ,key])=>key===module)?.[1]||'EduSync';
  const shortLabels:Record<string,string>={home:'Accueil',students:'Élèves',finance:'Finance',documents:'Documents'};
  const shellNav:ShellNavItem[]=visibleNav.map(([icon,label,key])=>({key,label,icon,active:module===key,onSelect:()=>goModule(key),primary:['home','students','finance','documents'].includes(key),shortLabel:shortLabels[key]}));
  const yearLabel=selectedYear?.label;
  const account:ShellAccount={name:session.user.full_name,email:session.user.email,context:`${session.school.name} · ${session.school.code}`,detail:yearLabel?(/^ann[ée]e/i.test(yearLabel)?yearLabel:`Année ${yearLabel}`):undefined,items:[
    {key:'profile',label:'Mon profil',icon:'user',onSelect:()=>setDialog('profile')},
    ...(canOpenModule('settings')?[{key:'settings',label:'Paramètres de l’école',icon:'settings',onSelect:()=>goModule('settings')}]:[]),
    {key:'security',label:'Sécurité et appareils',icon:'shield',onSelect:()=>setDialog('security')},
    {key:'logout',label:'Se déconnecter',icon:'logout',onSelect:onLogout,danger:true}]};
  const yearSelect=(where:string)=>shellYears.length>0&&<label className={`es-year es-year-${where}`} title="Année scolaire consultée"><NavGlyph g="calendar" size={15}/><span>Année</span><select aria-label="Année scolaire consultée" value={selectedYearId} onChange={e=>selectShellYear(e.target.value)}>{shellYears.map(y=><option key={y.id} value={y.id} title={y.status==='ACTIVE'?'Année en cours':y.status==='CLOSED'?'Année clôturée':undefined}>{y.code||y.label}</option>)}</select></label>;
  const tools=<>{yearSelect('top')}<StatusChip compact={false}/>{session.permissions.includes('notifications.internal.read')&&<NotificationBell token={session.token} canDismiss={session.permissions.includes('notifications.internal.dismiss')}/>}</>;
  return <AppShell orgLabel={session.school.name} orgCode={session.school.code} drawerTools={yearSelect('drawer')} nav={shellNav} title={currentLabel} context={`${session.school.name}${yearLabel?` · ${yearLabel}`:''}`} tools={tools} account={account}>
    <Suspense fallback={<ModuleLoader/>}>{module==='settings'?<SettingsPage session={session}/>:module==='personnel'?<PersonnelPage token={session.token} permissions={session.permissions} schoolName={session.school.name}/>:module==='students'?<SchoolingPage token={session.token} permissions={session.permissions} schoolName={session.school.name}/>:module==='headcounts'?<EffectifsPage token={session.token} permissions={session.permissions} schoolName={session.school.name} yearId={selectedYearId||undefined}/>:module==='finance'?<FinancePage token={session.token} permissions={session.permissions}/>:module==='documents'?<DocumentsPage token={session.token} permissions={session.permissions} schoolName={session.school.name}/>:module==='stewardship'?<StewardshipPage token={session.token} permissions={session.permissions}/>:module==='sync'?<SyncAdminPage token={session.token} permissions={session.permissions}/>:module==='access'?<AccessPage token={session.token} permissions={session.permissions} userName={session.user.full_name}/>:module==='home'?<HomePage token={session.token} permissions={session.permissions} schoolName={session.school.name} userName={session.user.full_name} onNavigate={goModule} yearId={selectedYearId||undefined} yearLabel={selectedYear?.label}/>:<Panel title="Module" subtitle="Ce module sera activé lorsqu’il disposera de ses contrats métier certifiés."><div/></Panel>}</Suspense>
    {dialog==='profile'&&<ProfileDialog name={session.user.full_name} email={session.user.email} context={`${session.school.name} · ${session.school.code}`} detail={yearLabel} onClose={()=>setDialog('')}/>}
    {dialog==='security'&&<SecurityDialog token={session.token} onClose={()=>setDialog('')} onPasswordChanged={onLogout}/>}
  </AppShell>}

export function App(){
  useEffect(()=>{const offBack=installMobileBackCoordinator();const offDirty=installUnsavedFormGuard();return()=>{offBack();offDirty()}},[]);
  const [platformToken,setPlatformToken]=useState('');
  const [platformUser,setPlatformUser]=useState<PlatformUser>({full_name:'',email:''});
  const [schoolSession,setSchoolSession]=useState<SavedSchoolSession|null>(null);
  const [restoring,setRestoring]=useState(true);
  useEffect(()=>{let alive=true;(async()=>{try{const r=await fetch('/api/v1/auth/refresh',{method:'POST',credentials:'include',cache:'no-store'});if(!r.ok)return;const d=await r.json();if(!alive||!d.access_token)return;if(d.scope==='SCHOOL'&&d.school&&d.user){setSchoolSession({token:d.access_token,school:d.school,user:d.user,permissions:d.permissions||[]})}else if(d.scope==='PLATFORM'){setPlatformToken(d.access_token);if(d.user)setPlatformUser({full_name:d.user.full_name,email:d.user.email})}}catch{/* aucune session persistante : afficher la connexion */}finally{if(alive)setRestoring(false)}})();return()=>{alive=false}},[]);
  useEffect(()=>{const h=(e:Event)=>{const d=(e as CustomEvent).detail||{};if(!d.token)return;if(d.scope==='SCHOOL')setSchoolSession(prev=>prev?{...prev,token:d.token}:prev);else setPlatformToken(d.token)};window.addEventListener('edusync:token-refreshed',h);return()=>window.removeEventListener('edusync:token-refreshed',h)},[]);
  function clear(){void fetch('/api/v1/auth/logout',{method:'POST',credentials:'include'}).catch(()=>{});localStorage.removeItem(PLATFORM_TOKEN);localStorage.removeItem(SCHOOL_SESSION);setPlatformToken('');setSchoolSession(null)}
  useEffect(()=>{if(!restoring)dismissBoot()},[restoring]);
  // While the persistent session is checked, the static boot screen (index.html) stays on screen: one continuous start.
  if(restoring)return null;
  if(schoolSession)return <SchoolApp session={schoolSession} onLogout={clear}/>;
  if(platformToken)return <AtelierPro token={platformToken} user={platformUser} onLogout={clear}/>;
  return <SecureLogin onPlatform={(token,user)=>{setPlatformUser(user);setPlatformToken(token)}} onSchool={setSchoolSession}/>;
}
